const { encode, decode } = require('./base64.js');
const e = (s, b) => { if (encode(s) !== b) { console.error('encode', JSON.stringify(s), '->', encode(s), 'want', b); process.exit(1); } };
e('', ''); e('f', 'Zg=='); e('fo', 'Zm8='); e('foo', 'Zm9v'); e('foob', 'Zm9vYg==');
e('fooba', 'Zm9vYmE='); e('foobar', 'Zm9vYmFy');
e('hello world', 'aGVsbG8gd29ybGQ=');
e('é', 'w6k=');
e('中文', '5Lit5paH');
for (const s of ['', 'a', 'ab', 'abc', 'hello world', 'éèê', '中文测试', '😀 emoji', 'x'.repeat(100)]) {
  if (decode(encode(s)) !== s) { console.error('round-trip failed for', JSON.stringify(s)); process.exit(1); }
}
for (const bad of ['abc', 'a', 'ab', '====', 'Zm9v!', 'a===']) {
  let threw = false; try { decode(bad); } catch (err) { threw = true; }
  if (!threw) { console.error('decode must reject', JSON.stringify(bad)); process.exit(1); }
}
const src = require('fs').readFileSync('base64.js', 'utf-8');
for (const banned of ['Buffer', 'atob', 'btoa', 'TextEncoder', 'TextDecoder']) {
  if (src.includes(banned)) { console.error('must not use', banned); process.exit(1); }
}
